from dataclasses import dataclass, field
import re
from typing import List, Dict, Any

@dataclass
class SwarmTopicKnowledgeBase:
    def get_topic_overview(self) -> dict:
        return {
            'discovered_topic': DISCOVERED_KNOWLEDGE['discovered_topic'],
            'domain_summary': DISCOVERED_KNOWLEDGE['domain_summary'],
            'executive_architecture_synthesis': DISCOVERED_KNOWLEDGE['executive_architecture_synthesis'],
            'architectural_concepts': DISCOVERED_KNOWLEDGE['architectural_concepts'],
            'operational_warnings': DISCOVERED_KNOWLEDGE['operational_warnings'],
            'total_catalog_items': len(DISCOVERED_KNOWLEDGE['catalog_entries']),
            'participating_families': {entry['extracted_by_family'] for entry in DISCOVERED_KNOWLEDGE['catalog_entries']}
        }

    def list_catalog(self) -> List[Dict[str, Any]]:
        return DISCOVERED_KNOWLEDGE['catalog_entries']

    def get_section_guides(self) -> List[Dict[str, Any]]:
        return DISCOVERED_KNOWLEDGE['section_guides']

    def get_jury_audit_trail(self) -> List[Dict[str, Any]]:
        return DISCOVERED_KNOWLEDGE['constitutional_jury_reviews']

    def recommend_for_task(self, task_description: str) -> List[Dict[str, Any]]:
        tokens = re.findall(r'[a-z0-9_-]{2,}', task_description.lower())
        catalog_entries = DISCOVERED_KNOWLEDGE['catalog_entries']
        
        def score_entry(entry):
            fields_to_check = ['name', 'category', 'capabilities', 'sub_components', 'workflow_steps']
            score = 0
            for field in fields_to_check:
                if isinstance(entry[field], str):
                    score += sum(1 for token in tokens if token in entry[field].lower())
                elif isinstance(entry[field], list):
                    score += sum(1 for token in tokens if any(token in item.lower() for item in entry[field]))
            return score
        
        catalog_entries.sort(key=score_entry, reverse=True)
        return catalog_entries

    def get_installation_playbook(self, item_name: str) -> dict:
        item_name_lower = item_name.lower()
        for entry in DISCOVERED_KNOWLEDGE['catalog_entries']:
            if item_name_lower in entry['name'].lower():
                return {
                    'name': entry['name'],
                    'source_or_ref': entry['source_or_ref'],
                    'install_commands': entry['install_commands'],
                    'usage_or_slash_commands': entry['usage_or_slash_commands'],
                    'workflow_steps': entry['workflow_steps'],
                    'cautions': entry['cautions']
                }
        return {}

    def evaluate_guardrails(self, content: str) -> dict:
        advisories = []
        content_lower = content.lower()
        
        for warning in DISCOVERED_KNOWLEDGE['operational_warnings']:
            if any(token in content_lower for token in re.findall(r'[a-z0-9_-]{2,}', warning.lower())):
                advisories.append(warning)
        
        for entry in DISCOVERED_KNOWLEDGE['catalog_entries']:
            for caution in entry['cautions']:
                if any(token in content_lower for token in re.findall(r'[a-z0-9_-]{2,}', caution.lower())):
                    advisories.append(caution)
        
        return {'advisories': advisories, 'warning_count': len(advisories)}

if __name__ == '__main__':
    knowledge_base = SwarmTopicKnowledgeBase()
    overview = knowledge_base.get_topic_overview()
    print("Topic Overview:", overview)
    print("Catalog Size:", overview['total_catalog_items'])
